package com.sigtm.backend.controller;
import com.sigtm.backend.model.HistorialOrdenCompra; import com.sigtm.backend.service.CompraService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/compras") @RequiredArgsConstructor public class HistorialOrdenCompraController { private final CompraService service; @GetMapping("/{id}/historial") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<HistorialOrdenCompra>> historial(@PathVariable Long id){return ResponseEntity.ok(service.historial(id));}}
